 reg=read(HERE/'pre_registration.json');calls=read(HERE/'solver_calls.json');assert len(calls)==12 and all(x['completed'] for x in calls);anchor=get(HERE/'objects',reg['candidate_witness']);old=get(HERE/'objects',reg['initial_witness']);E0=H*sum(F(x)**2 for c in CARS for u in old['controls'][c] for x in u);Ea=H*sum(F(x)**2 for c in CARS for u in anchor['controls'][c] for x in u);comparisons=[];details=[];timings=[];communication=[];activity=[];deadline=[];indexes=[];primary={}
