 l=next(x for x in comparisons if x['arm']=='L-new');c=next(x for x in comparisons if x['arm']=='C-new');oldrow=comparisons[0];reject=read(HERE/'results/rejection/independent_acceptance.json');Lpass=all(a['accepted'] for e in read(HERE/'results/L-new/summary.json')['events'] for a in e['admissions']);criteria=dict(theory_conditions=dict(status='passed',evidence='v3 explicit planes, M2 deadlines, atlas certification and all declared progress zero anchors'),physical_contract_change=dict(status='passed',evidence='one actual physical transition per numerical arm; four-car closure and resource/plane diffs'),activity_expansion=dict(status='passed',old_first_two=json.loads(oldrow['first_two_A']),new_first_two=json.loads(l['first_two_A']),newly_active=reg['added'],primary_maximum=3,four_car_goal='not achieved in the bounded waiting-advance pool; old four-car preparation is regression only'),multi_car_update=dict(status='partial',C_new_accepted_by_round=[0,0],L_new_accepted_by_round=[3,3],reason='C-v1 admission failures retained; L-v3 achieved three independent accepted numerical candidates on two actual successors'),continuation=dict(status='passed' if reject['passed'] else 'failed',evidence='true round-2 sources, shifted Gi/K, real-candidate two-layer rejection suffixes independently replayed'),completion=dict(status='passed',steps=[x['actual_steps'] for x in comparisons],B_final=0),same_version_controlled_comparison=dict(status='pending',reason='C-v1 and L-v3 have different physical planes and terminal equality encoding; do not infer submission-performance effects'))
 gate=dict(passed=False,status='partial',criteria=criteria,native_solver_calls=len(calls),native_solver_limit=16,unused_calls=16-len(calls),states=collections.Counter(x['status'] for x in calls),accepted_actual_numerical_candidates=sum(x['accepted'] for x in comparisons),C_v1_failure_calls_counted=True,L_v3_three_car_two_round_goal=Lpass,physical_source_same=True,anchor_controls_same=True,controlled_comparison_valid=False,formal_batch=False,next_required='new version and six C-new-v3 calls for a complete two-round three-car matched comparison; original C arm already used six of its cap eight')
 fork=read(HERE/'results/four_car_fork/summary.json');fork_audit=read(HERE/'results/four_car_fork/independent_acceptance.json');assert fork['passed'] and fork_audit['passed'];gate['four_car_diagnostic_fork']=dict(passed=True,first_activity=4,next_activity=3,new_calls=0,not_original_pool=True,not_main_numerical_arm=True);gate['criteria']['activity_expansion']['four_car_goal']='main numerical window achieved 3; post-experiment W_hold-suffix diagnostic fork certified 4 then 3 with zero solver calls';gate['next_required']='incorporate the certified W_hold suffix into one shared pool and preregister matched C/L two rounds (4 then3 per arm,14 new calls); alternatively six C-v3 calls complete only the existing three-car comparison'
 write(HERE/'GATE.json',gate);write(HERE/'metrics.json',dict(comparison=comparisons,events=details,timing=timings,primary_windows=primary,anchor_only_gain_vs_R_old_percent=float((E0-Ea)/E0*100),current_physical_difference=read(HERE/'physical_contract_diff.json')))
 inventory=read(HERE/'source_inventory.json');checked=0
 for path,h in inventory['files_sha256'].items():assert sha(Path(path))==h,path;checked+=1
 write(HERE/'preservation_check.json',dict(passed=True,historical_and_instruction_files=checked,papers_modified=False,git_commit=False));write(HERE/'usage.json',dict(measured_native_solver_calls=len(calls),limit=16,unused=4,measured_token_usage=None,billing_not_inferred_from_hooks=True))
 text=['# dynamic_groups_002 实验报告','','日期：2026-11-14，Asia/Shanghai。**结论：三车扩大与L-new连续两轮已实现；本轮整体部分完成，公平C/L比较待补。**','','## 先回答五个问题','','1. **谁从等待变成活动？** A1在同一真实源第41拍由旧合同保持转为有向倒车连接推进，首拍0.02m，下一拍继续兑现配额；A2、B2同时有效推进。R-old这两拍活动数2，数值两臂新合同锚点均为3，L-new两轮各三份新求解受理。','2. **什么物理合同改变？** A1删除等待16拍（两次8拍），原首动57变41。共同分离面及核心资源许可41开始、释放702（旧55开始、718释放）实际改变；原A1源阶段v≥0改为合法倒车负速度阶段。所有修改面/资源/接收端点形成四车闭包。不是组标签改名。完整n/beta物理单位差分在physical_contract_diff.json，原C-v1差分及预登记均保留。','3. **最高几车、持续几拍？** 主机制窗口三车；L-new主窗口连续三车长度为'+str(l['primary_longest_A_ge_3'])+'拍，首两拍都三车。全任务初始准备阶段原本就有四车，单列基础回归，不能算本轮释放保持车得到的四车成果。有限深2提前池内新增活动4未找到：最早新起步41，B1初准备40结束；不是一般几何不可达证明。','4. **局部优化额外改善多少？** 解析新锚点（提前本身不改变路线总控制代价，三点起步校正单列）相对R-old完整控制输入代价改善'+f"{float((E0-Ea)/E0*100):.8f}%"+'；L-new在新锚点上额外改善'+f"{l['extra_gain_vs_new_anchor_percent']:.8f}%"+'。预测32拍收益不累加，完整实际代价按唯一绝对拍号计费，包含实际K74，旧K73被覆盖。不是电池能耗。','5. **怎样接续并完成？** L-new从第41拍实际联合后继在42拍重建本车源、导数、模型、接收/K及剩余配额；固定首次物理面后自然拆分单车事务。三臂均2802拍/560.4s完成，B下降到0，A1目标从813提前到797，整体瓶颈未缩短。','','## 数值结果与版本边界','','|臂|调用/受理|两轮受理数|首两拍活动数|目标/保持|','|---|---:|---|---|---|',f"|R-old|0/0|—|{oldrow['first_two_A']}|2802拍完成|",f"|C-new-v1|6/0|0、0|{c['first_two_A']}|新合同锚点回退完成|",f"|L-new-v3|6/6|3、3|{l['first_two_A']}|真实新候选完成|",'', '实际新增调用12/16，C/L各6不超过各自8上限。C-v1原始状态5 Solved、1 AlmostSolved；L-v3六次均AlmostSolved。数值状态与完整certificate_suboptimal_v1受理分开，不能用Solved替代原行/物理验收。x/s/z、迭代、残差/gap、量化与拒绝行全部保留。', '', 'C-v1的六次失败调用没有被抹掉或重标。A1的旧分离面构造选中了刚可行方向，cap≈2.43296e−5m，接收位置/航向半径小于候选重放积分包络；A2/B2的Gi速度半径为零，但该等式未进入保和量化块，造成精确终端速度行微小违反。按两层回退安全执行锚点。', '', '在零新增调用下修共同规则：近距离轴候选全部取最大间隔，选中合同cap提升到约0.073828m；Gi零半径端点等式统一编译到量化合同。原网格、Q预算、h/N、模型与求解容差均未放宽。保留旧原始向量仅作回归夹具，数值来源校验明确拒绝把它们冒充新合同/新源求解。修复后L-new使用真实新调用通过。', '', '**公平比较门禁待完成。** C-v1与L-v3的物理面和冗余端点编码不同，提交耗时/输入收益不能归因于全组或局部组织的单独效果。完整受控对照须另设C-new-v3两轮三车的6次预算；当前剩余4次且C分臂只余2次，无法按原口径补齐，不追加凑数调用。', '', '## 有限池、理论条件与验收', '', '完整源扫描优先4、其次3、其次新增2。所选41拍保留16份完整候选，13份通过、3份因第710拍核心资源占用重叠拒绝。先验认证后按(-A,-P,B,J,ID)选择A1提前16；J用完整真实尾段输入代价。v3扩大可用分离轴集合，旧轴仍在候选中、支持间隔不减；同一16份控制及3个资源冲突不变，所选合同重新完整认证，旧可行证书按身份保留。', '', 'MA定理A/B只针对已生成并认证的有限提案池；三车目标与四车池限制分别列出。60类合法mode进度图册有直线/圆弧投影、倒车方向、管域唯一性和梯度/Hessian界；历史弯道真实源的非线性进度Taylor零锚点通过。实际进度、运动路程和求解集合在activity_trace.jsonl.gz分开，不以微小数值蠕动计有效推进。', '', 'M2/安全：六对连续旋转矩形、道路、排他资源、接收/K/完整后续和期限绑定均完整检查。DG递归延续/MA定理C：worker异常使用新合同内锚点，物理事务缺ACK全闭包回旧合同，固定外界面后某单车块失败时外部新候选继续；已保存实际拒绝后续并独立重放。完成：目标后合法零保持持续纳入占用与B检查。', '', '三臂完整独立8子段重放已通过；共享整数区间/ZOH、变分和锥编译，独立重算物理面、100项区间投影、活动、原始数值到有理命令、真实K/后续、资源和期限。旧源版本按source_archive与executed_source_versions.C_v1.json可恢复，不用新生成器伪重建旧模型。', '', '## 指标和计时口径', '', 'comparison.csv包含全任务A≥2/3/4拍数、主机制持续人数、逐车等待/有向进度/路程/目标时间、输入代价与实际期限；activity_trace和deadline_trace逐拍保留。per_event.csv列逐车逐轮受理/增量与原始数值。L-new首轮四车物理迁移合并、次轮固定物理面后拆分；C始终全四车提交，fork机制另列。', '', 'timing.csv使用事件真实共同释放到选择时间，分别记录准备、依赖核对、提交、选择、worker CPU与启动、实际重叠。worker Pipe实际JSON payload字节与应用协议JSON消息字节分开，均不含底层framing/网络包。本轮逻辑h=.2不代表实时；外层stage墙钟包含先验门禁驻留等待，应使用事件周期及独立验收内部wall_s，不能用stage外层等待冒充计算。版本不同及每臂仅两周期，禁止加速比/P95或因果效率宣称。', '', '## 下一轮最小任务', '', '1. 新版本分配6次C-new-v3调用，保持当前L-v3合同、提案、代价与进度机制，补齐两轮三车同版本对照。','2. 用同一有限池规则拓展等待前移连接/静止交接节点，探索比当前深2池更早的合法第四车活动，不改η和物理地图。','3. 独立正式重复实验再评价通信、并行时间与缩时效率。', '', '原论文、001及指令包保持；无Git提交。整体GATE为partial/false，三车活动扩大、L两轮受理、物理迁移、接续与完成可分别通过。']
 text+=['','## 补充：四车状态零调用诊断（不混入主样本）','','主实验结束后检查已有W_hold连接：源39拍A1已满足v=delta=0及合法W_hold，其两拍等待反馈为恒等映射。使用已有运动后缀、等待前移8+8并去掉2拍恒等反馈，得到总运动提前18拍的诊断变体。未修改主池或重挑数值窗口，源39旧活动为A2/B1/B2，新锚点四车均达到η，下一拍为三车。四辆车同一局部入口的零锚点、完整物理合同及到目标控制重放通过；独立检查99拍覆盖四个K71与G_in138交接。全程新增求解0，O为空。该fork未进行四车数值优化，不计作主臂四车MPC达标。','','原有限池使用带两拍反馈的完整连接，所以其4车受限结论保持原范围；新的已有W_hold后缀揭示了池覆盖不足，而不是道路不能容纳四车。证据位于results/four_car_fork/。下一版最小的双目标方案是纳入此连接变体，重新统一预登记C/L，第一轮4车、第二轮3车，两臂总14次新调用，兼顾四车与同版本公平对照。若只补当前三车对照，另6次C-v3即可。']
